import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const THEMES = {
  midnight: {
    name: 'Midnight Zen',
    bg: 'bg-[#0f0f1a]',
    blobs: ['bg-purple-900/20', 'bg-blue-900/20'],
    accent: 'text-purple-400',
    button: 'bg-purple-600 hover:bg-purple-500',
    isPremium: false
  },
  rainyTokyo: {
    name: 'Rainy Tokyo',
    bg: 'bg-[#1a1a2e]',
    blobs: ['bg-indigo-900/30', 'bg-slate-800/30'],
    accent: 'text-indigo-300',
    button: 'bg-indigo-700 hover:bg-indigo-600',
    isPremium: true
  },
  ghibliLibrary: {
    name: 'Ghibli Library',
    bg: 'bg-[#2d3436]',
    blobs: ['bg-green-900/20', 'bg-yellow-900/20'],
    accent: 'text-green-400',
    button: 'bg-green-700 hover:bg-green-600',
    isPremium: true
  },
  deepSpace: {
    name: 'Deep Space',
    bg: 'bg-[#020205]',
    blobs: ['bg-blue-900/40', 'bg-pink-900/20'],
    accent: 'text-pink-400',
    button: 'bg-pink-700 hover:bg-pink-600',
    isPremium: true
  }
};

const StudyChill = () => {
  const [timer, setTimer] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [tasks, setTasks] = useState([]);
  const [newTask, setNewTask] = useState('');
  const [currentTheme, setCurrentTheme] = useState('midnight');
  const [isPremium, setIsPremium] = useState(false);
  const [showPaywall, setShowPaywall] = useState(false);
  const [sounds, setSounds] = useState({ rain: 0.5, cafe: 0.2, fireplace: 0, lofi: 0.7 });

  // Reward System State
  const [totalStudyTime, setTotalStudyTime] = useState(0);
  const [rewardUnlocked, setRewardUnlocked] = useState(false);
  const [tempPremiumTheme, setTempPremiumTheme] = useState(null);

  useEffect(() => {
    let interval = null;
    if (isActive && timer > 0) {
      interval = setInterval(() => {
        setTimer((t) => t - 1);
        setTotalStudyTime(prev => prev + 1);
      }, 1000);
    } else if (timer === 0) {
      clearInterval(interval);
      alert("Time for a break!");
    }
    return () => clearInterval(interval);
  }, [isActive, timer]);

  // Reward Logic: 1 hour (3600s) of study unlocks a random premium theme for 1 hour
  useEffect(() => {
    if (totalStudyTime >= 3600 && !isPremium && !rewardUnlocked) {
      setRewardUnlocked(true);
    }
  }, [totalStudyTime, isPremium, rewardUnlocked]);

  const handleThemeChange = (themeKey) => {
    if (THEMES[themeKey].isPremium && !isPremium && tempPremiumTheme !== themeKey) {
      setShowPaywall(true);
    } else {
      setCurrentTheme(themeKey);
    }
  };

  const claimReward = () => {
    const premiumThemes = Object.keys(THEMES).filter(k => THEMES[k].isPremium);
    const randomTheme = premiumThemes[Math.floor(Math.random() * premiumThemes.length)];
    setTempPremiumTheme(randomTheme);
    setCurrentTheme(randomTheme);
    setRewardUnlocked(false); // Reset reward for next milestone

    // Set timer to remove temporary theme after 1 hour
    setTimeout(() => {
      setTempPremiumTheme(null);
      setCurrentTheme('midnight');
    }, 3600 * 1000);
  };

  const addTask = () => {
    if (newTask.trim()) {
      setTasks([...tasks, { id: Date.now(), text: newTask, completed: false }]);
      setNewTask('');
    }
  };

  const toggleTask = (id) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  const theme = THEMES[currentTheme];

  return (
    <div className={`min-h-screen ${theme.bg} text-[#e0e0e0] font-sans transition-colors duration-700 relative overflow-hidden`}>

      <div className={`absolute top-[-10%] left-[-10%] w-[500px] h-[500px] ${theme.blobs[0]} rounded-full blur-[120px] animate-pulse`} />
      <div className={`absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] ${theme.blobs[1]} rounded-full blur-[120px] animate-pulse`} />

      <nav className="flex justify-between items-center p-8 max-w-7xl mx-auto relative z-10">
        <div className={`text-2xl font-bold tracking-tighter ${theme.accent}`}>StudyChill.</div>
        <div className="flex gap-6 items-center">
          <div className="flex items-center gap-2 text-sm text-gray-400">
            <span className="w-2 h-2 bg-green-500 rounded-full animate-ping" />
            <span>1,420 studying now</span>
          </div>
          <button className="bg-white/10 hover:bg-white/20 px-4 py-2 rounded-full text-sm transition-all backdrop-blur-md border border-white/10">Login</button>
        </div>
      </nav>

      <main className="relative z-10 flex flex-col lg:flex-row items-start justify-center gap-12 px-6 py-12 max-w-7xl mx-auto">

        <div className="flex-1 flex flex-col items-center w-full">
          <motion.div 
            layout
            className="w-full max-w-md bg-white/5 backdrop-blur-2xl border border-white/10 p-12 rounded-[3rem] text-center shadow-2xl"
          >
            <h2 className="text-xs uppercase tracking-[0.3em] text-gray-500 mb-6">Focus Session</h2>
            <div className="text-8xl font-light tracking-tighter mb-10 tabular-nums text-white">
              {formatTime(timer)}
            </div>
            <div className="flex gap-4 justify-center">
              <button 
                onClick={() => setIsActive(!isActive)}
                className={`px-12 py-4 rounded-full font-bold transition-all transform hover:scale-105 ${isActive ? 'bg-red-500/20 text-red-400 border border-red-500/50' : `${theme.button} text-white shadow-lg`}`}
              >
                {isActive ? 'Pause' : 'Start Study'}
              </button>
              <button 
                onClick={() => {setIsActive(false); setTimer(25 * 60);}}
                className="bg-white/10 hover:bg-white/20 px-6 py-4 rounded-full transition-all"
              >
                Reset
              </button>
            </div>
          </motion.div>

          {/* Reward Banner */}
          <AnimatePresence>
            {rewardUnlocked && (
              <motion.div 
                initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }}
                className="mt-8 bg-gradient-to-r from-yellow-600 to-orange-600 p-4 rounded-2xl flex items-center gap-4 shadow-xl shadow-orange-500/20"
              >
                <span className="text-2xl">🎁</span>
                <div className="flex-1">
                  <p className="text-sm font-bold text-white">Study Milestone Reached!</p>
                  <p className="text-xs text-orange-100">You've earned a random Premium Theme for 1 hour.</p>
                </div>
                <button 
                  onClick={claimReward}
                  className="bg-white text-orange-600 px-4 py-2 rounded-xl text-xs font-bold hover:bg-orange-50 transition-all"
                >
                  Claim
                </button>
              </motion.div>
            )}
          </AnimatePresence>

          <div className="mt-12 w-full max-w-md">
            <h3 className="text-center text-sm text-gray-500 mb-4 uppercase tracking-widest">Change Atmosphere</h3>
            <div className="flex justify-center gap-3 flex-wrap">
              {Object.entries(THEMES).map(([key, val]) => (
                <button 
                  key={key} onClick={() => handleThemeChange(key)}
                  className={`px-4 py-2 rounded-full text-xs transition-all border ${currentTheme === key ? 'bg-white text-black border-white' : 'bg-white/5 text-gray-400 border-white/10 hover:bg-white/10'}`}
                >
                  {val.name} {val.isPremium && '⭐'}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-12 w-full max-w-md">
            {Object.entries(sounds).map(([name, value]) => (
              <div key={name} className="bg-white/5 backdrop-blur-md border border-white/10 p-4 rounded-2xl flex flex-col items-center gap-3">
                <span className="capitalize text-xs text-gray-400">{name}</span>
                <input 
                  type="range" min="0" max="1" step="0.1" 
                  value={value} 
                  onChange={(e) => setSounds({...sounds, [name]: parseFloat(e.target.value)})}
                  className="w-full accent-purple-500"
                />
              </div>
            ))}
          </div>
        </div>

        <div className="w-full lg:w-96 flex flex-col gap-6">
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 p-6 rounded-3xl shadow-xl">
            <h3 className="text-lg font-medium mb-4 flex items-center gap-2"><span>🎯</span> Session Goals</h3>
            <div className="flex gap-2 mb-4">
              <input 
                type="text" value={newTask} onChange={(e) => setNewTask(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && addTask()}
                placeholder="What are we studying?"
                className="flex-1 bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-purple-500 transition-all"
              />
              <button onClick={addTask} className="bg-purple-600 p-2 rounded-lg hover:bg-purple-500 transition-all">+</button>
            </div>
            <div className="space-y-2 max-h-60 overflow-y-auto pr-2">
              {tasks.map(task => (
                <div key={task.id} onClick={() => toggleTask(task.id)} className="flex items-center gap-3 p-2 rounded-lg hover:bg-white/5 cursor-pointer transition-all group">
                  <div className={`w-5 h-5 rounded-full border ${task.completed ? 'bg-purple-500 border-purple-500' : 'border-gray-500'} transition-all`} />
                  <span className={`text-sm ${task.completed ? 'line-through text-gray-500' : 'text-gray-300'}`}>{task.text}</span>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white/5 backdrop-blur-xl border border-white/10 p-6 rounded-3xl shadow-xl">
            <h3 className="text-lg font-medium mb-4 flex items-center gap-2"><span>👥</span> Live Now</h3>
            <div className="space-y-4">
              {[ { name: 'Sasha', topic: 'Biology', time: '2h' }, { name: 'Leo', topic: 'Physics', time: '45m' }, { name: 'Mia', topic: 'History', time: '1h' } ].map((user, i) => (
                <div key={i} className="flex items-center justify-between text-sm">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-gradient-to-br from-purple-500 to-blue-500 rounded-full" />
                    <div className="font-medium">{user.name} <span className="text-gray-500 font-normal">is studying</span> {user.topic}</div>
                  </div>
                  <span className="text-xs text-gray-500">{user.time}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </main>

      <AnimatePresence>
        {showPaywall && (
          <motion.div 
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
          >
            <motion.div 
              initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }}
              className="bg-[#1a1a2e] border border-white/20 p-10 rounded-[3rem] max-w-md w-full text-center shadow-2xl"
            >
              <div className="text-5xl mb-6">⭐</div>
              <h2 className="text-2xl font-bold mb-4">Unlock Premium Themes</h2>
              <p className="text-gray-400 mb-8">Get access to Rainy Tokyo, Ghibli Library, and Deep Space to maximize your focus.</p>
              <button 
                onClick={() => {setIsPremium(true); setShowPaywall(false);}}
                className="w-full bg-purple-600 py-4 rounded-full font-bold hover:bg-purple-500 transition-all transform hover:scale-105 shadow-lg shadow-purple-500/30"
              >
                Upgrade to Premium (₹99)
              </button>
              <button onClick={() => setShowPaywall(false)} className="mt-4 text-sm text-gray-500 hover:text-gray-300 transition-all">Maybe later</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="text-center py-12 relative z-10">
        <p className="text-gray-600 text-sm italic">"Peace is the prerequisite for focus."</p>
      </footer>
    </div>
  );
};

export default StudyChill;
